const express = require('express');
const { Server } = require('@tus/server');
const { FileStore } = require('@tus/file-store');
const { verifyDoctorJwt } = require('../middleware/auth');
const { db } = require('../db');

const app = express();

const tusServer = new Server({
  path: '/files',
  datastore: new FileStore({ directory: './uploads/dicom' }),
  onUploadCreate: async (req, res, upload) => {
    const patientCaseId = upload.metadata.patientCaseId;
    const assignment = await db.query(
      'SELECT id FROM doctor_patient_cases WHERE case_id = $1 AND doctor_id = $2',
      [patientCaseId, req.doctor.id]
    );
    if (!assignment.rows.length) {
      throw { status_code: 403, body: 'Forbidden: doctor is not assigned to this patient case' };
    }
    return res;
  },
});

app.all('/files*', verifyDoctorJwt, (req, res) => {
  tusServer.handle(req, res);
});
